export type IconAnimation =
  | 'beat'
  | 'fade'
  | 'beat-fade'
  | 'bounce'
  | 'flip'
  | 'flip-360'
  | 'shake'
  | 'spin'
  | 'spin-pulse'
  | 'spin-reverse'
  | 'spin-snap'
  | 'spin-snap-4'
  | 'spin-snap-8'
  | 'buzz'
  | 'wag'
  | 'float'
  | 'swing'
  | 'jello';

export type IconCanvas = 'fixed' | 'auto' | 'square' | 'roomy';

