                  part: 'previous-button',
                  targetPage: this.page - 1,
                  enabled: !onFirstPage,
                  label: this.localize.term('previousPage'),
                  icon: isRtl ? 'chevron-right' : 'chevron-left',
                  slotName: 'previous-icon',
