        this.animationCleanups.get(el)?.abort();
        const cleanup = new AbortController();
        this.animationCleanups.set(el, cleanup);
        htmlEl.addEventListener('animationend', () => delete htmlEl.dataset['waAnimation'], {
          once: true,
          signal: cleanup.signal,
        });
      });
