      this.hasScrollControls =
        ['top', 'bottom'].includes(this.placement) && this.nav.scrollWidth > this.nav.clientWidth + 1;
    }
  }

  render() {
    const isRtl = this.hasUpdated ? this.localize.dir() === 'rtl' : this.dir === 'rtl';

    return html`
      <div
        part="base tab-group"
        class=${classMap({
          'tab-group': true,
          'tab-group-top': this.placement === 'top',
          'tab-group-bottom': this.placement === 'bottom',
          'tab-group-start': this.placement === 'start',
          'tab-group-end': this.placement === 'end',
          'tab-group-has-scroll-controls': this.hasScrollControls,
        })}
        @click=${this.handleClick}
        @keydown=${this.handleKeyDown}
      >
        <div class="nav-container" part="nav">
          ${this.hasScrollControls
            ? html`
                <wa-button
                  part="scroll-button scroll-button-start"
                  exportparts="base:scroll-button__base"
                  class="scroll-button scroll-button-start"
                  appearance="plain"
                  @click=${this.handleScrollToStart}
                >
                  <wa-icon
                    name=${isRtl ? 'chevron-right' : 'chevron-left'}
                    library="system"
                    variant="solid"
                    label=${this.localize.term('scrollToStart')}
                  ></wa-icon>
                </wa-button>
              `
            : ''}

          <!-- We have a focus listener because in Firefox (and soon to be Chrome) overflow containers are focusable. -->
          <div class="nav" @focus=${() => this.activeTab?.focus({ preventScroll: true })}>
            <div part="tabs" class="tabs" role="tablist">
              <slot name="nav" @slotchange=${this.syncTabsAndPanels}></slot>
            </div>
          </div>

          ${this.hasScrollControls
            ? html`
                <wa-button
                  part="scroll-button scroll-button-end"
                  class="scroll-button scroll-button-end"
                  exportparts="base:scroll-button__base"
                  appearance="plain"
                  @click=${this.handleScrollToEnd}
                >
                  <wa-icon
                    name=${isRtl ? 'chevron-left' : 'chevron-right'}
                    library="system"
                    variant="solid"
                    label=${this.localize.term('scrollToEnd')}
                  ></wa-icon>
                </wa-button>
              `
            : ''}
        </div>

        <div part="body" class="body"><slot @slotchange=${this.syncTabsAndPanels}></slot></div>
      </div>
    `;
  }
