/**
 * Use a generator so we can iterate and possibly break early.
 * @example
 *   // to operate like a regular array. This kinda nullifies generator benefits, but worth knowing if you need the whole array.
 *   const allActiveElements = [...activeElements()]
 *
 *   // Early return
 *   for (const activeElement of activeElements()) {
 *     if (<cond>) {
 *       break; // Break the loop, don't need to iterate over the whole array or store an array in memory!
 *     }
 *   }
 */
export function* activeElements(activeElement: Element | null = document.activeElement): Generator<Element> {
  if (activeElement === null || activeElement === undefined) return;

  yield activeElement;

  if ('shadowRoot' in activeElement && activeElement.shadowRoot && activeElement.shadowRoot.mode !== 'closed') {
    yield* activeElements(activeElement.shadowRoot.activeElement);
  }
}

export function getDeepestActiveElement() {
  return [...activeElements()].pop();
}

/** Same as `el.animate()`, except returns a promise that doesn't throw an error when the animation is canceled. */
export async function animate(el: Element, keyframes: Keyframe[], options?: KeyframeAnimationOptions) {
  return el.animate(keyframes, options).finished.catch(() => {
    /* suppress errors in Safari */
  });
}

/**
 * Applies a class to the specified element, waits for its finite CSS animations to finish or be canceled, then removes
 * the class. Transitions and animations created with the Web Animations API do not delay completion.
 */
export async function animateWithClass(el: Element, className: string) {
  // Flush a previous class removal so immediately reusing the class starts a fresh animation.
  el.getAnimations();
  el.classList.add(className);

  // Popup activation is reactive; let its display styles render before sampling animations.
  await new Promise<void>(resolve => requestAnimationFrame(() => resolve()));

  const animationPromises: Promise<Animation>[] = [];

  for (const animation of el.getAnimations()) {
    if (animation instanceof CSSAnimation && animation.effect?.getComputedTiming().endTime !== Infinity) {
      animationPromises.push(animation.finished);
    }
  }

  await Promise.allSettled(animationPromises);
  el.classList.remove(className);
}

/** Parses a CSS duration and returns the number of milliseconds. */
export function parseDuration(duration: number | string) {
  duration = duration.toString().toLowerCase();

  if (duration.indexOf('ms') > -1) {
    return parseFloat(duration) || 0;
  }

  if (duration.indexOf('s') > -1) {
    return (parseFloat(duration) || 0) * 1000;
  }

  return parseFloat(duration) || 0;
}

/** Tells if the user has enabled the "reduced motion" setting in their browser or OS. */
export function prefersReducedMotion() {
  const query = window.matchMedia('(prefers-reduced-motion: reduce)');
  return query.matches;
}

import type { ReactiveController, ReactiveControllerHost } from 'lit';

export class ColorSchemeController implements ReactiveController {
  private host: ReactiveControllerHost & Element;
  private hiddenElement: HTMLElement;
  private onThemeChange: () => void;

  constructor(host: ReactiveControllerHost & Element, onThemeChange: () => void) {
    (this.host = host).addController(this);
    this.onThemeChange = onThemeChange;

    // Hidden element — inherits CSS from nearest themed ancestor
    if (typeof document !== 'undefined') {
      this.hiddenElement = document.createElement('div');
      this.hiddenElement.setAttribute('aria-hidden', 'true');
      Object.assign(this.hiddenElement.style, {
        position: 'absolute',
        width: '0',
        height: '0',
        overflow: 'hidden',
        pointerEvents: 'none',
        opacity: '0',
        // Transition on a WA surface token — changes whenever the theme class changes
        color: 'var(--wa-color-surface-default, transparent)',
        transition: 'color 0.001ms',
      });
    }
  }

  hostConnected() {
    if (this.hiddenElement) {
      this.host.appendChild(this.hiddenElement);
      this.hiddenElement.addEventListener('transitionend', this.handleTransitionEnd);
    }
  }

  hostDisconnected() {
    if (this.hiddenElement) {
      this.hiddenElement.removeEventListener('transitionend', this.handleTransitionEnd);
      this.hiddenElement.remove();
    }
  }

  private handleTransitionEnd = () => {
    this.onThemeChange();
  };
}

// Cached computed style calls.
// computedStyle calls are "live" so they only need to be retrieved once for an element.
export const computedStyleMap = new WeakMap<Element, CSSStyleDeclaration>();

export function getComputedStyle(el: Element): CSSStyleDeclaration | null {
  let computedStyle: undefined | CSSStyleDeclaration = computedStyleMap.get(el);

  if (!computedStyle && globalThis.window) {
    computedStyle = window.getComputedStyle(el);
    computedStyleMap.set(el, computedStyle);
  }

  return computedStyle ?? null;
}

// @debounce decorator
//
// Delays the execution until the provided delay in milliseconds has
// passed since the last time the function has been called.
//
//
// Usage:
//
//  @debounce(1000)
//  handleInput() {
//    ...
//  }
//

// Each class instance will need to store its timer id, so this unique symbol will be used as property key.
const TIMER_ID_KEY = Symbol();

export const debounce = (delay: number) => {
  return <T>(_target: T, _propertyKey: string, descriptor: PropertyDescriptor) => {
    const fn = descriptor.value as (this: T & { [TIMER_ID_KEY]: number }, ...args: unknown[]) => unknown;

    descriptor.value = function (this: ThisParameterType<typeof fn>, ...args: Parameters<typeof fn>) {
      clearTimeout(this[TIMER_ID_KEY]);

      this[TIMER_ID_KEY] = window.setTimeout(() => {
        fn.apply(this, args);
      }, delay);
    };
  };
};

// @defaultValue decorator
//
// Runs when the corresponding attribute of the observed property changes, e.g. after calling Element.setAttribute or after updating
// the observed property.
//
// The decorator checks whether the value of the attribute is different from the value of the property and in that case
// it saves the new value.
//
//
// Usage:
//
//  @property({ type: Boolean, reflect: true }) checked = false;
//
//  @defaultValue('checked') defaultChecked = false;
//

import type { ReactiveElement } from 'lit';
import { defaultConverter } from 'lit';

export const defaultValue =
  (propertyName = 'value') =>
  (proto: ReactiveElement, key: string) => {
    const ctor = proto.constructor as typeof ReactiveElement;

    const attributeChangedCallback = ctor.prototype.attributeChangedCallback;
    ctor.prototype.attributeChangedCallback = function (
      this: ReactiveElement & { [name: string]: unknown },
      name,
      old,
      value,
    ) {
      const options = ctor.getPropertyOptions(propertyName);
      const attributeName = typeof options.attribute === 'string' ? options.attribute : propertyName;

      if (name === attributeName) {
        const converter = options.converter || defaultConverter;
        const fromAttribute =
          typeof converter === 'function' ? converter : (converter?.fromAttribute ?? defaultConverter.fromAttribute);

        const newValue: unknown = fromAttribute!(value, options.type);

        if (this[propertyName] !== newValue) {
          this[key] = newValue;
        }
      }

      attributeChangedCallback.call(this, name, old, value);
    };
  };

/**
 * Shared dismissible stack for keyboard event coordination.
 *
 * Dismissible components (drawer, dialog, select, dropdown, tooltip, popover, color-picker) each attach their own
 * document keydown listener. Without coordination, all open dismissibles respond to the Escape key simultaneously,
 * causing nested dismissibles to all close at once.
 *
 * This maintains an ordered stack of open dismissibles. Each component registers itself when opening and unregisters
 * when closing. Before handling Escape, components call `isTopDismissible()` to confirm they are the topmost (most
 * recently opened) dismissible.
 */
const dismissibleStack: object[] = [];

/**
 * Registers a dismissible as open. Call this when the dismissible becomes visible.
 * The most recently registered dismissible is at the top.
 */
export function registerDismissible(key: object): void {
  // Move an already registered dismissible to the top instead of duplicating it. This can happen when a prevented hide
  // event reverts a dismissible back to open.
  unregisterDismissible(key);
  dismissibleStack.push(key);
}

/**
 * Unregisters a dismissible. Call this when the dismissible closes or is removed from the DOM.
 */
export function unregisterDismissible(key: object): void {
  for (let i = dismissibleStack.length - 1; i >= 0; i--) {
    if (dismissibleStack[i] === key) {
      dismissibleStack.splice(i, 1);
      break;
    }
  }
}

/**
 * Returns true if the given key is the topmost registered dismissible.
 * Use this to guard Escape key handling so only the topmost dismissible responds.
 */
export function isTopDismissible(key: object): boolean {
  return dismissibleStack.length > 0 && dismissibleStack[dismissibleStack.length - 1] === key;
}

interface DragOptions {
  /** Callback that runs as dragging occurs. */
  onMove: (x: number, y: number) => void;
  /** Callback that runs when dragging stops. */
  onStop: () => void;
  /**
   * When an initial event is passed, the first drag will be triggered immediately using the coordinates therein. This
   * is useful when the drag is initiated by a mousedown/touchstart event but you want the initial "click" to activate
   * a drag (e.g. positioning a handle initially at the click target).
   */
  initialEvent: PointerEvent;
}

/** Begins listening for dragging. */
export function drag(container: HTMLElement, options?: Partial<DragOptions>) {
  function move(pointerEvent: PointerEvent) {
    const dims = container.getBoundingClientRect();
    const defaultView = container.ownerDocument.defaultView!;
    const offsetX = dims.left + defaultView.pageXOffset;
    const offsetY = dims.top + defaultView.pageYOffset;
    const x = pointerEvent.pageX - offsetX;
    const y = pointerEvent.pageY - offsetY;

    if (options?.onMove) {
      options.onMove(x, y);
    }
  }

  function stop() {
    document.removeEventListener('pointermove', move);
    document.removeEventListener('pointerup', stop);

    if (options?.onStop) {
      options.onStop();
    }
  }

  document.addEventListener('pointermove', move, { passive: true });
  document.addEventListener('pointerup', stop);

  // If an initial event is set, trigger the first drag immediately
  if (options?.initialEvent instanceof PointerEvent) {
    move(options.initialEvent);
  }
}

const supportsTouch = typeof window !== 'undefined' && 'ontouchstart' in window;

/**
 * Attaches the necessary events to make an element draggable.
 *
 * This by itself will not make the element draggable, but it provides the events and callbacks necessary to facilitate
 * dragging. Use the `clientX` and `clientY` arguments of each callback to update the UI as desired when dragging.
 *
 * Drag functionality will be enabled as soon as the constructor is called. A `start()` and `stop()` method can be used
 * to start and stop it, if needed.
 *
 * Use `touch-action: none` on touch devices if scrolling occurs while dragging. Avoid preventing the touchstart event!
 *
 * @usage
 *
 * const draggable = new DraggableElement(element, {
 *   start: (clientX, clientY) => { ... },
 *   move: (clientX, clientY) => { ... },
 *   stop: (clientX, clientY) => { ... }
 * });
 */
export class DraggableElement {
  private element: Element;
  private isActive = false;
  private isDragging = false;
  private options: DraggableElementOptions;

  constructor(el: Element, options: Partial<DraggableElementOptions>) {
    this.element = el;
    this.options = {
      start: () => undefined,
      stop: () => undefined,
      move: () => undefined,
      ...options,
    };

    this.start();
  }

  private handleDragStart = (event: PointerEvent | TouchEvent) => {
    const clientX = 'touches' in event ? event.touches[0].clientX : (event as PointerEvent).clientX;
    const clientY = 'touches' in event ? event.touches[0].clientY : (event as PointerEvent).clientY;

    if (
      this.isDragging ||
      // Prevent right-clicks from triggering drags
      (!supportsTouch && (event as PointerEvent).buttons > 1)
    ) {
      return;
    }

    this.isDragging = true;

    document.addEventListener('pointerup', this.handleDragStop);
    document.addEventListener('pointermove', this.handleDragMove);
    document.addEventListener('pointercancel', this.handleDragStop);
    document.addEventListener('touchend', this.handleDragStop);
    document.addEventListener('touchmove', this.handleDragMove);
    document.addEventListener('touchcancel', this.handleDragStop);
    this.options.start(clientX, clientY);
  };

  private handleDragStop = (event: PointerEvent | TouchEvent) => {
    const clientX = 'changedTouches' in event ? event.changedTouches[0].clientX : (event as PointerEvent).clientX;
    const clientY = 'changedTouches' in event ? event.changedTouches[0].clientY : (event as PointerEvent).clientY;

    this.isDragging = false;
    document.removeEventListener('pointerup', this.handleDragStop);
    document.removeEventListener('pointermove', this.handleDragMove);
    document.removeEventListener('pointercancel', this.handleDragStop);
    document.removeEventListener('touchend', this.handleDragStop);
    document.removeEventListener('touchmove', this.handleDragMove);
    document.removeEventListener('touchcancel', this.handleDragStop);
    this.options.stop(clientX, clientY);
  };

  private handleDragMove = (event: PointerEvent | TouchEvent) => {
    const clientX = 'touches' in event ? event.touches[0].clientX : (event as PointerEvent).clientX;
    const clientY = 'touches' in event ? event.touches[0].clientY : (event as PointerEvent).clientY;

    // Prevent text selection while dragging
    window.getSelection()?.removeAllRanges();

    this.options.move(clientX, clientY);
  };

  /** Start listening to drags. */
  public start() {
    if (!this.isActive) {
      this.element.addEventListener('pointerdown', this.handleDragStart);
      if (supportsTouch) {
        this.element.addEventListener('touchstart', this.handleDragStart);
      }
      this.isActive = true;
    }
  }

  /** Stop listening to drags. */
  public stop() {
    document.removeEventListener('pointerup', this.handleDragStop);
    document.removeEventListener('pointermove', this.handleDragMove);
    document.removeEventListener('pointercancel', this.handleDragStop);
    document.removeEventListener('touchend', this.handleDragStop);
    document.removeEventListener('touchmove', this.handleDragMove);
    document.removeEventListener('touchcancel', this.handleDragStop);
    this.element.removeEventListener('pointerdown', this.handleDragStart);
    if (supportsTouch) {
      this.element.removeEventListener('touchstart', this.handleDragStart);
    }
    this.isActive = false;
    this.isDragging = false;
  }

  /** Starts or stops the drag listeners. */
  public toggle(isActive?: boolean) {
    const isGoingToBeActive = isActive !== undefined ? isActive : !this.isActive;

    if (isGoingToBeActive) {
      this.start();
    } else {
      this.stop();
    }
  }
}

export interface DraggableElementOptions {
  /** Runs when dragging starts. */
  start: (clientX: number, clientY: number) => void;
  /** Runs as the user is dragging. This may execute often, so avoid expensive operations. */
  move: (clientX: number, clientY: number) => void;
  /** Runs when dragging ends. */
  stop: (clientX: number, clientY: number) => void;
}

/** Waits for a specific event to be emitted from an element. Ignores events that bubble up from child elements. */
export function waitForEvent(el: HTMLElement, eventName: string) {
  return new Promise<void>(resolve => {
    function done(event: Event) {
      if (event.target === el) {
        el.removeEventListener(eventName, done);
        resolve();
      }
    }

    el.addEventListener(eventName, done);
  });
}

/**
 * Like textContent, but better:
 * - Uses assignedNodes to get text content from slots (and falls back to content if nothing is slotted)
 * - Ignores script and style elements
 * @param root - One or more nodes to get text content from.
 * @param depth - By default, will just return element.textContent for any child elements instead of calling the function recursively.
 *                Set to a positive integer to recurse that many levels. Generally a tradeoff between performance and accuracy.
 * @returns
 */
export default function getText(root: Node | Iterable<Node>, depth = 0): string {
  if (!root || !globalThis.Node) {
    return '';
  }

  if (typeof (root as any)[Symbol.iterator] === 'function') {
    let nodes = Array.isArray(root) ? root : [...(root as Iterable<Node>)];
    return nodes.map(node => getText(node, --depth)).join('');
  }

  let node = root as Node;

  if (node.nodeType === Node.TEXT_NODE) {
    return node.textContent ?? '';
  }

  if (node.nodeType === Node.ELEMENT_NODE) {
    let element = node as HTMLElement;

    if (element.hasAttribute('slot') || element.matches('style, script')) {
      return '';
    }

    if (element instanceof HTMLSlotElement) {
      let assignedNodes = element.assignedNodes({ flatten: true });

      if (assignedNodes.length > 0) {
        // If no assigned nodes, we still want the slot contents
        return getText(assignedNodes, --depth);
      }
    }

    return depth > -1 ? getText(element, --depth) : (element.textContent ?? '');
  }

  return node.hasChildNodes() ? getText(node.childNodes, --depth) : '';
}

/**
 * A shared, light-DOM live region for announcing dynamic updates to screen readers.
 *
 * Live regions rendered inside a shadow root are not reliably announced — notably, JAWS + Firefox ignores them
 * entirely. To work around this, we maintain a single visually-hidden live region appended to `document.body` (light
 * DOM) and update its contents imperatively. This mirrors the approach used by Adobe's React Aria `LiveAnnouncer` and is
 * the most robust way to ensure announcements are picked up across screen readers.
 *
 * The region is created lazily and persists for the lifetime of the page. Each announcement appends a fresh node (so
 * repeating the same message still announces) and removes it shortly after, preventing stale text from accumulating or
 * being re-read when focus returns.
 */

type Politeness = 'polite' | 'assertive';

let politeLog: HTMLElement | null = null;
let assertiveLog: HTMLElement | null = null;

/** How long an announcement node lingers before it's removed, in milliseconds. */
const CLEAR_DELAY = 7_000;

function createLog(politeness: Politeness): HTMLElement {
  const log = document.createElement('div');
  log.setAttribute('role', 'log');
  log.setAttribute('aria-live', politeness);
  log.setAttribute('aria-relevant', 'additions');

  // Visually hidden, but not removed from the accessibility tree (which `display: none` / `hidden` would do).
  Object.assign(log.style, {
    position: 'absolute',
    width: '1px',
    height: '1px',
    margin: '-1px',
    padding: '0',
    border: '0',
    overflow: 'hidden',
    clip: 'rect(0 0 0 0)',
    clipPath: 'inset(50%)',
    whiteSpace: 'nowrap',
  } satisfies Partial<CSSStyleDeclaration>);

  return log;
}

function getLog(politeness: Politeness): HTMLElement {
  if (politeness === 'assertive') {
    assertiveLog ??= document.body.appendChild(createLog('assertive'));
    return assertiveLog;
  }

  politeLog ??= document.body.appendChild(createLog('polite'));
  return politeLog;
}

/**
 * Announces a message to assistive technology via a shared light-DOM live region.
 *
 * @param message - The text to announce. Empty strings are ignored.
 * @param politeness - Whether to announce politely (default) or assertively.
 */
export function announce(message: string, politeness: Politeness = 'polite') {
  if (!message) return;

  const log = getLog(politeness);
  const node = document.createElement('div');
  node.textContent = message;
  log.appendChild(node);

  setTimeout(() => node.remove(), CLEAR_DELAY);
}

import { nanoid } from 'nanoid';

/** Ensures a number stays within a minimum and maximum value */
export function clamp(value: number, min: number, max: number) {
  const noNegativeZero = (n: number) => (Object.is(n, -0) ? 0 : n);

  if (value < min) {
    return noNegativeZero(min);
  }

  if (value > max) {
    return noNegativeZero(max);
  }

  return noNegativeZero(value);
}

/* Generates a random, unique id with an optional prefix. */
export function uniqueId(prefix = '') {
  return `${prefix}${nanoid()}`;
}

/**
 * Returns an element's offset relative to its parent. Similar to element.offsetTop and element.offsetLeft, except the
 * parent doesn't have to be positioned relative or absolute.
 *
 * NOTE: This was created to work around what appears to be a bug in Chrome where a slotted element's offsetParent seems
 * to ignore elements inside the surrounding shadow DOM: https://bugs.chromium.org/p/chromium/issues/detail?id=920069
 */
export function getOffset(element: HTMLElement, parent: HTMLElement) {
  return {
    top: Math.round(element.getBoundingClientRect().top - parent.getBoundingClientRect().top),
    left: Math.round(element.getBoundingClientRect().left - parent.getBoundingClientRect().left),
  };
}

/** Returns true when a mouse or pointer event's coordinates fall within the element's border box. */
export function isEventInsideRect(event: MouseEvent, el: Element) {
  const rect = el.getBoundingClientRect();
  return (
    event.clientX >= rect.left &&
    event.clientX <= rect.right &&
    event.clientY >= rect.top &&
    event.clientY <= rect.bottom
  );
}

/** Parses a space-delimited set of tokens and returns an array with all whitespace removed. */
export function parseSpaceDelimitedTokens(input: string): string[] {
  return input
    .split(' ')
    .map(token => token.trim())
    .filter(token => token !== '');
}

import { isServer } from 'lit';

/**
 * Watches an element and reports when it stops or starts generating layout boxes, e.g. when third-party CSS applies
 * "display: none" to it or an ancestor. A ResizeObserver signals changes and getClientRects() determines the state,
 * since it distinguishes "not rendered" from "rendered at zero size". Visibility and opacity never count as hidden.
 */
export class RenderedWatcher {
  private observer: ResizeObserver | undefined;
  private initialCheckHandle: number | undefined;

  constructor(
    private readonly element: HTMLElement,
    private readonly callback: (isRendered: boolean) => void,
  ) {}

  /**
   * Starts watching and reports the current state on the next frame. Additional targets also act as change signals,
   * e.g. an internal element that always has a non-zero box when rendered.
   */
  start(...additionalTargets: Element[]) {
    if (isServer) {
      return;
    }

    this.observer ??= new ResizeObserver(() => this.check());

    this.observer.observe(this.element);

    for (const target of additionalTargets) {
      this.observer.observe(target);
    }

    // ResizeObserver doesn't deliver an initial observation for elements that aren't rendered, so check once in case
    // the element is already hidden. Deferred to the next frame because a synchronous layout flush here, right after
    // showModal(), can hang Firefox and WebKit.
    this.initialCheckHandle ??= requestAnimationFrame(() => {
      this.initialCheckHandle = undefined;
      this.check();
    });
  }

  /** Stops watching. */
  stop() {
    if (this.initialCheckHandle !== undefined) {
      cancelAnimationFrame(this.initialCheckHandle);
      this.initialCheckHandle = undefined;
    }

    this.observer?.disconnect();
  }

  private check() {
    this.callback(this.element.getClientRects().length > 0);
  }
}

import { getOffset } from './offset.js';

const locks = new Set();

/** Returns the width of the document's scrollbar */
function getScrollbarWidth() {
  const documentWidth = document.documentElement.clientWidth;
  return Math.abs(window.innerWidth - documentWidth);
}

/**
 * Used in conjunction with `scrollbarWidth` to set proper body padding in case the user has padding already on the `<body>` element.
 */
function getExistingBodyPadding() {
  const padding = Number(getComputedStyle(document.body).paddingRight.replace(/px/, ''));

  if (isNaN(padding) || !padding) {
    return 0;
  }

  return padding;
}

/**
 * Prevents body scrolling. Keeps track of which elements requested a lock so multiple levels of locking are possible
 * without premature unlocking.
 */
export function lockBodyScrolling(lockingEl: HTMLElement) {
  locks.add(lockingEl);

  // When the first lock is created, set the scroll lock size to match the scrollbar's width to prevent content from
  // shifting. We only do this on the first lock because the scrollbar width will measure zero after overflow is hidden.
  if (!document.documentElement.classList.contains('wa-scroll-lock')) {
    /** Scrollbar width + body padding calculation can go away once Safari has scrollbar-gutter support. */
    const scrollbarWidth = getScrollbarWidth() + getExistingBodyPadding(); // must be measured before the `wa-scroll-lock` class is applied

    let scrollbarGutterProperty = getComputedStyle(document.documentElement).scrollbarGutter;

    // default is auto, unsupported browsers is "undefined"
    if (!scrollbarGutterProperty || scrollbarGutterProperty === 'auto') {
      scrollbarGutterProperty = 'stable';
    }

    /** Sometimes the scrollbar width is 1px, even then, we assume nothing is overflowing. */
    if (scrollbarWidth < 2) {
      // if there's no scrollbar, just set it to an empty string so whatever the user has set gets used. This is useful if the page is not overflowing and showing a scrollbar, or if the user has overflow: hidden, or any other reason a scrollbar may not be showing.
      scrollbarGutterProperty = '';
    }
    document.documentElement.style.setProperty('--wa-scroll-lock-gutter', scrollbarGutterProperty);
    document.documentElement.classList.add('wa-scroll-lock');
    document.documentElement.style.setProperty('--wa-scroll-lock-size', `${scrollbarWidth}px`);
  }
}

/**
 * Unlocks body scrolling. Scrolling will only be unlocked once all elements that requested a lock call this method.
 */
export function unlockBodyScrolling(lockingEl: HTMLElement) {
  locks.delete(lockingEl);

  if (locks.size === 0) {
    document.documentElement.classList.remove('wa-scroll-lock');
    document.documentElement.style.removeProperty('--wa-scroll-lock-size');
  }
}

/** Scrolls an element into view of its container. If the element is already in view, nothing will happen. */
export function scrollIntoView(
  element: HTMLElement,
  container: HTMLElement,
  direction: 'horizontal' | 'vertical' | 'both' = 'vertical',
  behavior: 'smooth' | 'auto' = 'smooth',
) {
  const offset = getOffset(element, container);
  const offsetTop = offset.top + container.scrollTop;
  const offsetLeft = offset.left + container.scrollLeft;
  const minX = container.scrollLeft;
  const maxX = container.scrollLeft + container.offsetWidth;
  const minY = container.scrollTop;
  const maxY = container.scrollTop + container.offsetHeight;

  if (direction === 'horizontal' || direction === 'both') {
    if (offsetLeft < minX) {
      container.scrollTo({ left: offsetLeft, behavior });
    } else if (offsetLeft + element.clientWidth > maxX) {
      container.scrollTo({ left: offsetLeft - container.offsetWidth + element.clientWidth, behavior });
    }
  }

  if (direction === 'vertical' || direction === 'both') {
    if (offsetTop < minY) {
      container.scrollTo({ top: offsetTop, behavior });
    } else if (offsetTop + element.clientHeight > maxY) {
      container.scrollTo({ top: offsetTop - container.offsetHeight + element.clientHeight, behavior });
    }
  }
}

import { isServer } from 'lit';

type GenericCallback = (this: unknown, ...args: unknown[]) => unknown;

type MethodOf<T, K extends keyof T> = T[K] extends GenericCallback ? T[K] : never;

(() => {
  // Don't need polyfills on the server
  if (isServer) {
    return;
  }

  const debounce = <T extends GenericCallback>(fn: T, delay: number) => {
    let timerId = 0;

    return function (this: unknown, ...args: unknown[]) {
      window.clearTimeout(timerId);
      timerId = window.setTimeout(() => {
        fn.call(this, ...args);
      }, delay);
    };
  };

  const decorate = <T, M extends keyof T>(
    proto: T,
    method: M,
    decorateFn: (this: unknown, superFn: T[M], ...args: unknown[]) => unknown,
  ) => {
    const superFn = proto[method] as MethodOf<T, M>;

    proto[method] = function (this: unknown, ...args: unknown[]) {
      superFn.call(this, ...args);
      decorateFn.call(this, superFn, ...args);
    } as MethodOf<T, M>;
  };

  const isSupported = 'onscrollend' in window;

  if (!isSupported) {
    const pointers = new Set();
    const scrollHandlers = new WeakMap<EventTarget, EventListenerOrEventListenerObject>();

    const handlePointerDown = (event: PointerEvent) => {
      pointers.add(event.pointerId);
    };

    const handlePointerUp = (event: PointerEvent) => {
      pointers.delete(event.pointerId);
    };

    document.addEventListener('pointerdown', handlePointerDown);
    document.addEventListener('pointerup', handlePointerUp);

    decorate(EventTarget.prototype, 'addEventListener', function (this: EventTarget, addEventListener, type) {
      if (type !== 'scroll') return;

      const handleScrollEnd = debounce(() => {
        if (!pointers.size) {
          // If no pointer is active in the scroll area then the scroll has ended
          this.dispatchEvent(new Event('scrollend'));
        } else {
          // otherwise let's wait a bit more
          handleScrollEnd();
        }
      }, 100);

      addEventListener.call(this, 'scroll', handleScrollEnd, { passive: true });
      scrollHandlers.set(this, handleScrollEnd);
    });

    decorate(EventTarget.prototype, 'removeEventListener', function (this: EventTarget, removeEventListener, type) {
      if (type !== 'scroll') return;

      const scrollHandler = scrollHandlers.get(this);
      if (scrollHandler) {
        removeEventListener.call(this, 'scroll', scrollHandler, { passive: true } as unknown as EventListenerOptions);
      }
    });
  }
})();

// Without an import or export, TypeScript sees vars in this file as global
export {};

/**
 * `SegmentedFieldController` — a reactive controller that wires the **keystroke and focus mechanics** for a segmented
 * input. It is the generic skeleton used by `<wa-date-input>` and `<wa-time-input>`, and is intentionally agnostic
 * about what the segments represent.
 *
 * What it owns:
 *  - Per-segment digit buffer (the raw chars the user is typing before commit).
 *  - Roving tabindex and the "active segment" pointer used by host render and focus restore.
 *  - Arrow Up/Down stepping, Arrow Left/Right navigation (with RTL inversion), Home/End, Backspace/Delete,
 *    separator-advance, Tab flush.
 *
 * What it does NOT own (the host plugs these in via `SegmentRules`):
 *  - The meaning of the segments (date fields, time fields, anything else).
 *  - Per-field digit typing semantics (when to commit, when to advance, when to overflow-replace).
 *  - Per-field bounds and stepping rules (wraparound, leap years, AM/PM, …).
 *  - Layout derivation (the host builds a `SegmentLayout` from the locale and passes it in each render).
 *  - The popup, validation, hidden form input, or any DOM beyond the segment elements themselves.
 *
 * The controller is **DOM-aware** (it reads `[data-group]`/`[data-segment]` attrs from the host's shadow root and
 * dispatches focus on them), but it has no knowledge of the host's render tree — the host renders segments however it
 * likes as long as those two data attributes are present.
 *
 * Why a controller instead of a class mixin: Web Awesome form controls already extend
 * `WebAwesomeFormAssociatedElement`, and date/time pickers need different validators on top of that base. A
 * ReactiveController composes cleanly without forcing inheritance and can be tested in isolation against a synthetic
 * host.
 */

import type { ReactiveController, ReactiveControllerHost } from 'lit';

//
// Public types
//

/** A field identifier — opaque to the controller. The host defines the strings (e.g. `'month'`, `'hour'`). */
export type SegmentField = string;

/** A group identifier — opaque to the controller. Single-group hosts can use a fixed string like `'single'`. */
export type SegmentGroup = string;

/** One editable segment in the layout. */
export interface SegmentToken {
  kind: 'segment';
  field: SegmentField;
}

/** Inert text rendered between segments (separator, suffix, …). The host renders this verbatim. */
export interface LiteralToken {
  kind: 'literal';
  text: string;
}

export type LayoutToken = SegmentToken | LiteralToken;

/** The ordered list of layout tokens for the current locale. */
export interface SegmentLayout {
  tokens: LayoutToken[];
  /** Just the segment fields, in order — convenience for focus/advance logic. */
  order: SegmentField[];
}

/** Result of typing a digit into a segment. */
export interface TypeDigitResult {
  /** The segment's new value (host-defined type), or `null` if still effectively empty. */
  value: unknown;
  /** The raw digit buffer still being accumulated. Empty once committed. */
  buffer: string;
  /** When true, the controller advances focus to the next segment. */
  advance: boolean;
}

/** Result of stepping a segment (Arrow Up / Down). */
export interface StepResult {
  /** The new value for the stepped segment. */
  value: unknown;
}

/** Inclusive numeric bounds for a segment, used for `aria-valuemin`/`aria-valuemax`. */
export interface SegmentBounds {
  min: number;
  max: number;
}

/**
 * Host-provided per-field rules. The controller calls these to apply user actions; the host owns the meaning.
 */
export interface SegmentRules {
  /**
   * Apply a digit to the current buffer of `field` in `group`. The host knows the field's value semantics; the
   * controller blindly forwards the result.
   */
  typeDigit(group: SegmentGroup, field: SegmentField, buffer: string, digit: string): TypeDigitResult;

  /**
   * Step a field by `delta` (always ±1 — Page Up/Down can be wired by the host via a custom shortcut if needed).
   * The host may return `null` to indicate the step was a no-op (e.g., past a hard bound).
   */
  step(group: SegmentGroup, field: SegmentField, delta: -1 | 1): StepResult | null;

  /** Bounds for the field's spinbutton ARIA values. */
  bounds(group: SegmentGroup, field: SegmentField): SegmentBounds;

  /**
   * Commit a non-empty buffer as the field's value when the user navigates away. Returns the value to store, or `null`
   * to leave the segment empty.
   */
  commitBuffer(group: SegmentGroup, field: SegmentField, buffer: string): unknown;

  /**
   * Clear the field — used by Backspace/Delete on a committed value. Returns `true` if a value was actually cleared,
   * `false` if the field was already empty. The controller uses this to decide whether Backspace should additionally
   * jump focus to the previous segment.
   */
  clear(group: SegmentGroup, field: SegmentField): boolean;
}

/** Host-supplied side-effect hook fired when a segment's value changes. The host updates its model and re-renders. */
export type SegmentCommitListener = (group: SegmentGroup, field: SegmentField, value: unknown) => void;

/** Optional config for the controller. */
export interface SegmentedFieldControllerConfig {
  /**
   * Returns the layout for the current render. The host typically derives this from its current locale; we read it on
   * demand so locale changes reflect on the next interaction without controller surgery.
   */
  getLayout: (group: SegmentGroup) => SegmentLayout;

  /** True if the field is currently RTL. The controller flips logical left/right when computing nav direction. */
  isRtl: () => boolean;

  /** Per-field rules — required. */
  rules: SegmentRules;

  /** Fired after a segment's value changes (digit type, step, clear, buffer-flush). */
  onCommit?: SegmentCommitListener;

  /**
   * Characters that advance to the next segment without changing the current one. Defaults match common date/time
   * separators: `/`, `.`, `-`, `:`, `,`, and space. The host can override (e.g. add `'+'` for sign segments).
   */
  separatorKeys?: string[];

  /** Read-only mode — disables typing/stepping but still allows focus traversal. */
  isReadonly?: () => boolean;

  /** Disabled mode — disables everything (focus included; tab indices go to -1). */
  isDisabled?: () => boolean;
}

const DEFAULT_SEPARATORS = ['/', '.', '-', ':', ',', ' '];

//
// Controller
//

/**
 * Wires segment behavior into a Lit host. Construct one per host element.
 *
 * The host renders each segment with `data-group="<group>"` and `data-segment="<field>"` and binds the keyboard/focus
 * events returned by `eventHandlers()`. Everything else flows through the controller.
 */
export class SegmentedFieldController implements ReactiveController {
  private host: ReactiveControllerHost & Element;
  private config: SegmentedFieldControllerConfig;

  /** Per-segment digit buffers keyed by `${group}:${field}`. */
  private buffers: Map<string, string> = new Map();

  /** Which segment currently owns the roving tabindex / was most recently focused. */
  private active: { group: SegmentGroup; field: SegmentField } | null = null;

  constructor(host: ReactiveControllerHost & Element, config: SegmentedFieldControllerConfig) {
    this.host = host;
    this.config = config;
    host.addController(this);
  }

  //
  // ReactiveController lifecycle
  //

  hostConnected() {
    // Nothing — keyboard listeners are bound by the host on each segment via `eventHandlers()`.
  }

  hostDisconnected() {
    this.buffers.clear();
    this.active = null;
  }

  //
  // Public API
  //

  /** Get the buffer for a segment. Empty string when nothing is pending. */
  getBuffer(group: SegmentGroup, field: SegmentField): string {
    return this.buffers.get(this.key(group, field)) ?? '';
  }

  /** Replace the buffer for a segment. Pass `''` to clear. */
  setBuffer(group: SegmentGroup, field: SegmentField, buffer: string): void {
    const k = this.key(group, field);
    if (buffer) this.buffers.set(k, buffer);
    else this.buffers.delete(k);
  }

  /** Drop every pending buffer. Used by the host when the canonical value is replaced wholesale. */
  clearBuffers(): void {
    this.buffers.clear();
  }

  /** The active segment, or `null` if focus has never landed on one. */
  getActiveSegment(): { group: SegmentGroup; field: SegmentField } | null {
    return this.active;
  }

  /** Sets the active segment (does not move DOM focus). Used by hosts that programmatically restore focus. */
  setActiveSegment(group: SegmentGroup, field: SegmentField): void {
    this.active = { group, field };
  }

  /** All segment elements in the host's shadow root, in DOM (logical) order. */
  segmentElements(): HTMLElement[] {
    const root = this.host.shadowRoot;
    if (!root) return [];
    return Array.from(root.querySelectorAll<HTMLElement>('[data-segment][data-group]'));
  }

  /** The segment element for a given (group, field), or `null` if not in the DOM. */
  segmentElementFor(group: SegmentGroup, field: SegmentField): HTMLElement | null {
    const root = this.host.shadowRoot;
    if (!root) return null;
    return root.querySelector<HTMLElement>(`[data-group="${group}"][data-segment="${field}"]`);
  }

  /**
   * Returns the segment that should receive initial focus: the first empty segment (no value AND no buffer) per
   * `isEmpty`, otherwise the first segment in the layout. The host supplies the emptiness predicate since the
   * controller doesn't know the field's stored value.
   */
  findFocusableSegment(isEmpty: (group: SegmentGroup, field: SegmentField) => boolean): HTMLElement | null {
    const segments = this.segmentElements();
    if (segments.length === 0) return null;
    const firstEmpty = segments.find(el => {
      const group = el.dataset.group as SegmentGroup;
      const field = el.dataset.segment as SegmentField;
      return isEmpty(group, field) && !this.getBuffer(group, field);
    });
    return firstEmpty ?? segments[0];
  }

  /** Restore focus to the most recently active segment (or the first segment if none has been active). */
  focusActiveSegment(options?: FocusOptions): void {
    if (this.active) {
      const el = this.segmentElementFor(this.active.group, this.active.field);
      if (el) {
        el.focus({ preventScroll: true, ...options });
        return;
      }
    }
    this.segmentElements()[0]?.focus({ preventScroll: true, ...options });
  }

  /** Move focus to the neighbor segment in logical (DOM) order. */
  moveFocus(from: HTMLElement, direction: -1 | 1, options?: FocusOptions): void {
    const segments = this.segmentElements();
    const idx = segments.indexOf(from);
    if (idx < 0) return;
    const next = segments[idx + direction];
    if (next) next.focus({ preventScroll: true, ...options });
  }

  /**
   * Commit a pending buffer to its committed value via `rules.commitBuffer`. Notifies the host via `onCommit`. Does
   * nothing if no buffer is pending.
   */
  flushBuffer(group: SegmentGroup, field: SegmentField): boolean {
    const buffer = this.getBuffer(group, field);
    if (!buffer) return false;
    const value = this.config.rules.commitBuffer(group, field, buffer);
    this.setBuffer(group, field, '');
    this.config.onCommit?.(group, field, value);
    return true;
  }

  /**
   * Flush every pending buffer across all groups. Used when the host needs to read a final value (e.g., on form
   * submission outside of a focus change).
   */
  flushAllBuffers(): void {
    for (const [k, buffer] of this.buffers) {
      if (!buffer) continue;
      const [group, field] = k.split(':');
      const value = this.config.rules.commitBuffer(group, field, buffer);
      this.config.onCommit?.(group, field, value);
    }
    this.buffers.clear();
  }

  /**
   * Returns the event handlers a segment element should bind. Hosts wire these via `@keydown=${handlers.keydown}` etc.
   * The returned functions are stable references safe to pass to Lit's directive cache.
   *
   * Hosts that need host-level shortcuts (e.g. `Alt+ArrowDown` to open a popup) should call `handleKeyDown` themselves
   * after handling their own keys. The controller's `keydown` handler is safe to invoke when the host has not consumed
   * the event — it ignores keys it doesn't recognize.
   */
  eventHandlers() {
    return {
      keydown: this.handleKeyDown,
      focus: this.handleFocus,
      blur: this.handleBlur,
    };
  }

  /**
   * Direct entry point for hosts that wrap the controller's keydown with their own pre-handler (e.g. for popup
   * shortcuts). Returns `true` if the controller consumed the event (called `preventDefault`), `false` otherwise.
   */
  handleKeyDownEvent(event: KeyboardEvent): boolean {
    const defaultPreventedBefore = event.defaultPrevented;
    this.handleKeyDown(event);
    return event.defaultPrevented && !defaultPreventedBefore;
  }

  //
  // Internal handlers
  //

  private handleFocus = (event: FocusEvent) => {
    const el = event.currentTarget as HTMLElement;
    const group = el.dataset.group as SegmentGroup;
    const field = el.dataset.segment as SegmentField;
    this.active = { group, field };

    // Roving tabindex — Tab returns to this segment next time the host is entered.
    for (const segment of this.segmentElements()) {
      segment.tabIndex = segment === el ? 0 : -1;
    }
  };

  private handleBlur = (event: FocusEvent) => {
    const el = event.currentTarget as HTMLElement;
    const group = el.dataset.group as SegmentGroup;
    const field = el.dataset.segment as SegmentField;
    if (this.getBuffer(group, field)) this.flushBuffer(group, field);
  };

  private handleKeyDown = (event: KeyboardEvent) => {
    // `currentTarget` is the segment when bound as a Lit `@keydown` listener. If the host invokes this manually from
    // a different listener, fall back to walking `composedPath()` for the nearest segment element.
    const el =
      (event.currentTarget as HTMLElement | null) ??
      (event.composedPath().find(t => {
        return t instanceof HTMLElement && t.dataset.group && t.dataset.segment;
      }) as HTMLElement | undefined) ??
      null;
    if (!el) return;
    const group = el.dataset.group as SegmentGroup;
    const field = el.dataset.segment as SegmentField;
    if (!group || !field) return;

    // Stepping (Arrow Up / Down).
    if (event.key === 'ArrowUp' || event.key === 'ArrowDown') {
      event.preventDefault();
      if (this.isReadonlyOrDisabled()) return;
      // Any partial buffer flushes first so step operates on the committed value.
      if (this.getBuffer(group, field)) this.flushBuffer(group, field);
      const delta: -1 | 1 = event.key === 'ArrowUp' ? 1 : -1;
      const result = this.config.rules.step(group, field, delta);
      if (result) this.config.onCommit?.(group, field, result.value);
      return;
    }

    // Logical-direction nav (RTL inverts visual arrows).
    if (event.key === 'ArrowLeft' || event.key === 'ArrowRight') {
      event.preventDefault();
      if (this.getBuffer(group, field)) this.flushBuffer(group, field);
      const visualLeft = event.key === 'ArrowLeft';
      const logicalPrev = this.config.isRtl() ? !visualLeft : visualLeft;
      this.moveFocus(el, logicalPrev ? -1 : 1);
      return;
    }

    if (event.key === 'Home') {
      event.preventDefault();
      this.segmentElements()[0]?.focus({ preventScroll: true });
      return;
    }
    if (event.key === 'End') {
      event.preventDefault();
      const segments = this.segmentElements();
      segments[segments.length - 1]?.focus({ preventScroll: true });
      return;
    }

    if (event.key === 'Tab') {
      // Let the browser handle the focus move, but commit any pending buffer first.
      if (this.getBuffer(group, field)) this.flushBuffer(group, field);
      return;
    }

    if (event.key === 'Backspace' || event.key === 'Delete') {
      event.preventDefault();
      if (this.isReadonlyOrDisabled()) return;
      const buffer = this.getBuffer(group, field);
      if (buffer) {
        // Wipe just the partial — leave any prior committed value alone.
        this.setBuffer(group, field, '');
        this.config.onCommit?.(group, field, null);
      } else {
        const hadValue = this.config.rules.clear(group, field);
        if (hadValue) {
          this.config.onCommit?.(group, field, null);
        } else if (event.key === 'Backspace') {
          // Empty segment — Backspace jumps to the previous segment. Delete stays put.
          this.moveFocus(el, -1);
        }
      }
      return;
    }

    // Digit input.
    if (/^[0-9]$/.test(event.key)) {
      event.preventDefault();
      if (this.isReadonlyOrDisabled()) return;
      const buffer = this.getBuffer(group, field);
      const result = this.config.rules.typeDigit(group, field, buffer, event.key);
      this.setBuffer(group, field, result.buffer);
      this.config.onCommit?.(group, field, result.value);
      if (result.advance) this.moveFocus(el, 1);
      return;
    }

    // Separator: commit the buffer and advance.
    const seps = this.config.separatorKeys ?? DEFAULT_SEPARATORS;
    if (seps.includes(event.key)) {
      event.preventDefault();
      if (this.getBuffer(group, field)) this.flushBuffer(group, field);
      this.moveFocus(el, 1);
      return;
    }
  };

  //
  // Helpers
  //

  private key(group: SegmentGroup, field: SegmentField): string {
    return `${group}:${field}`;
  }

  private isReadonlyOrDisabled(): boolean {
    return !!(this.config.isReadonly?.() || this.config.isDisabled?.());
  }
}

/** Canonical size values. */
export type Size = 'xs' | 's' | 'm' | 'l' | 'xl';

/** Deprecated long-form size aliases. */
export type DeprecatedSize = 'small' | 'medium' | 'large';

/** All accepted size values (canonical + deprecated). */
export type SizeWithDeprecated = Size | DeprecatedSize;

const DEPRECATION_MAP: Record<DeprecatedSize, Size> = {
  small: 's',
  medium: 'm',
  large: 'l',
};

/** Normalizes a size value, mapping deprecated long forms to short forms. Returns the value unchanged if already canonical. */
export function normalizeSize(size: SizeWithDeprecated): Size {
  return (DEPRECATION_MAP as Record<string, Size>)[size] ?? (size as Size);
}

const warned = new Set<string>();

/** Emits a one-time console warning for deprecated size values. */
export function warnDeprecatedSize(tagName: string, value: string): void {
  if (value in DEPRECATION_MAP && !warned.has(`${tagName}:${value}`)) {
    warned.add(`${tagName}:${value}`);
    console.warn(
      `[${tagName}] size="${value}" is deprecated. Use size="${DEPRECATION_MAP[value as DeprecatedSize]}" instead. ` +
        `The long-form value will be removed in the next major version.`,
    );
  }
}

import type { ReactiveController, ReactiveControllerHost } from 'lit';

/** A reactive controller that determines when slots exist. */
export class HasSlotController implements ReactiveController {
  host: ReactiveControllerHost & HTMLElement;
  slotNames: string[] = [];

  constructor(host: typeof this.host, ...slotNames: string[]) {
    (this.host = host).addController(this);
    this.slotNames = slotNames;
  }

  private hasDefaultSlot() {
    // `Element#childNodes` is unavailable in Lit's SSR context
    if (!this.host.childNodes) {
      return false;
    }

    return [...this.host.childNodes].some(node => {
      if (node.nodeType === Node.TEXT_NODE && node.textContent!.trim() !== '') {
        return true;
      }

      if (node.nodeType === Node.ELEMENT_NODE) {
        const el = node as HTMLElement;
        const tagName = el.tagName.toLowerCase();

        // Ignore visually hidden elements since they aren't rendered
        if (tagName === 'wa-visually-hidden') {
          return false;
        }

        // If it doesn't have a slot attribute, it's part of the default slot
        if (!el.hasAttribute('slot')) {
          return true;
        }
      }

      return false;
    });
  }

  private hasNamedSlot(name: string) {
    return this.host.querySelector?.(`:scope > [slot="${name}"]`) !== null;
  }

  /**
   * @param slotName     - Name of the slot to look for
   * @param propertyName - Generally we infer via `withHeader` property on the host, but in cases where its different, you can specify a manual property name.
   */
  test(slotName: string, propertyName?: null | string) {
    // @ts-expect-error
    if (propertyName && this.host.didSSR && !this.host.hasUpdated) {
      // @ts-expect-error
      return Boolean(this.host[propertyName]);
    }

    return slotName === '[default]' ? this.hasDefaultSlot() : this.hasNamedSlot(slotName);
  }

  hostConnected() {
    const shadowRoot = this.host.shadowRoot;
    if (shadowRoot && 'addEventListener' in shadowRoot) {
      shadowRoot.addEventListener('slotchange', this.handleSlotChange);
    }
  }

  hostDisconnected() {
    const shadowRoot = this.host.shadowRoot;
    if (shadowRoot && 'removeEventListener' in shadowRoot) {
      shadowRoot.removeEventListener('slotchange', this.handleSlotChange);
    }
  }

  private handleSlotChange = (event: Event) => {
    const slot = event.target as HTMLSlotElement;

    if ((this.slotNames.includes('[default]') && !slot.name) || (slot.name && this.slotNames.includes(slot.name))) {
      this.host.requestUpdate();
    }
  };
}

/**
 * Given a list of nodes, this function iterates over all of them and returns the concatenated
 * HTML as a string. This is useful for getting the HTML that corresponds to a slot’s assigned nodes (since we can't use slot.innerHTML as an alternative).
 * @param nodes - The list of nodes to iterate over.
 * @param callback - A function that can be used to customize the HTML output for specific types of nodes. If the function returns undefined, the default HTML output will be used.
 */
export function getInnerHTML(nodes: Iterable<Node>, callback?: (node: Node) => string | undefined): string {
  let html = '';

  for (const node of nodes) {
    if (callback) {
      const customHTML = callback(node);

      if (customHTML !== undefined) {
        html += customHTML;
        continue;
      }
    }

    if (node.nodeType === Node.ELEMENT_NODE) {
      html += (node as HTMLElement).outerHTML;
    }

    if (node.nodeType === Node.TEXT_NODE) {
      html += node.textContent;
    }
  }

  return html;
}

import type WaButton from '../components/button/button.js';
import type { WebAwesomeFormAssociatedElement } from './webawesome-form-associated-element.js';

export function submitOnEnter<T extends HTMLElement>(event: KeyboardEvent, el: T) {
  const hasModifier = event.metaKey || event.ctrlKey || event.shiftKey || event.altKey;

  // Pressing enter when focused on an input should submit the form like a native input, but we wait a tick before
  // submitting to allow users to cancel the keydown event if they need to
  if (event.key === 'Enter' && !hasModifier) {
    // setTimeout in case the event is caught higher up in the tree and defaultPrevented
    setTimeout(() => {
      //
      // When using an Input Method Editor (IME), pressing enter will cause the form to submit unexpectedly. One way
      // to check for this is to look at event.isComposing, which will be true when the IME is open.
      //
      // See https://github.com/shoelace-style/shoelace/pull/988
      //
      if (!event.defaultPrevented && !event.isComposing) {
        submitForm(el);
      }
    });
  }
}

// Submittable inputs are all tags we know that are submittable by pressing "Enter".
// This is rough, and I may miss some, but its the best I could get to.
const submittableTags = new Map([
  ['input', true],
  ['wa-input', true],
  ['wa-tag-input', true],
  ['wa-number-input', true],
  ['wa-otp-input', true],
  ['wa-slider', true],
]);

// Pulled from sidebar here: <https://developer.mozilla.org/en-US/docs/Web/HTML/Reference/Elements/input/button>
const submittableTypes = new Map([
  ['button', false],
  ['checkbox', false],
  ['color', false],
  ['date', false],
  ['datetime-local', false],
  ['email', true],
  ['file', false],
  ['hidden', false],
  ['image', false],
  ['month', false],
  ['number', true],
  ['password', true],
  ['radio', false],
  ['range', false],
  ['reset', true],
  ['search', true],
  ['submit', false],
  ['tel', true],
  ['text', true],
  ['time', false],
  ['url', true],
  ['week', false],
]);

const isSubmittableElement = (el: Element) => {
  const tagName = el?.localName;
  if (!tagName) {
    return false;
  }

  const isSubmittableTag = Boolean(submittableTags.get(tagName));

  if (!isSubmittableTag) {
    return false;
  }

  // We dont need to typecheck unless the input is either `<wa-input>` or `<input>`
  if (tagName !== 'input' && tagName !== 'wa-input') {
    return true;
  }

  const type = (el as HTMLInputElement).type;
  return Boolean(submittableTypes.get(type));
};

export function submitForm(el: HTMLElement | WebAwesomeFormAssociatedElement) {
  let form: HTMLFormElement | null = null;

  if ('form' in el) {
    form = el.form as HTMLFormElement | null;
  }

  if (!form && 'getForm' in el) {
    form = el.getForm();
  }

  if (!form) {
    return;
  }

  const formElements = Array.from(form.elements);

  // The default button is the first submit button in tree order, disabled or not. A disabled default button blocks
  // Enter even when a later submit button is enabled, as it does natively.
  const button = formElements.find((el: HTMLButtonElement | HTMLInputElement) => el.type === 'submit') as
    | undefined
    | HTMLButtonElement
    | HTMLInputElement
    | WaButton;

  if (button) {
    if (button.matches(':disabled')) {
      return;
    }

    if (['input', 'button'].includes(button.localName)) {
      form.requestSubmit(button);
    } else {
      // requestSubmit() wont work with `<wa-button>`, so trigger a manual click.
      button.click();
    }
    return;
  }

  // Without a submit button, Enter submits only when a single field blocks implicit submission
  if (formElements.filter(isSubmittableElement).length === 1) {
    form.requestSubmit(null);
  }
}

import type { Validator } from '../webawesome-form-associated-element.js';

/**
 * This validator is for if you have an exact copy of your element in the shadow DOM. Rather than needing
 * custom translations and error messages, you can simply rely on the element "formControl" in your shadow dom.
 */
export const CustomErrorValidator = (): Validator => {
  return {
    observedAttributes: ['custom-error'],
    checkValidity(element) {
      const validity: ReturnType<Validator['checkValidity']> = {
        message: '',
        isValid: true,
        invalidKeys: [],
      };

      if (element.customError) {
        validity.message = element.customError;
        validity.isValid = false;
        validity.invalidKeys = ['customError'];
      }

      return validity;
    },
  };
};

import type { Validator } from '../webawesome-form-associated-element.js';

/**
 * This validator is for if you have an exact copy of your element in the shadow DOM. Rather than needing
 * custom translations and error messages, you can simply rely on the element "formControl" in your shadow dom.
 */
export const MirrorValidator = (): Validator => {
  return {
    checkValidity(element) {
      const formControl = element.input;

      const validity: ReturnType<Validator['checkValidity']> = {
        message: '',
        isValid: true,
        invalidKeys: [],
      };

      if (!formControl) {
        return validity;
      }

      let isValid = true;

      if ('checkValidity' in formControl) {
        isValid = formControl.checkValidity();
      }

      if (isValid) {
        return validity;
      }

      validity.isValid = false;

      if ('validationMessage' in formControl) {
        validity.message = formControl.validationMessage;
      }

      // For some reason formControl doesn't have "validity", so chalk it up to customError
      if (!('validity' in formControl)) {
        validity.invalidKeys.push('customError');
        return validity;
      }

      for (const key in formControl.validity) {
        if (key === 'valid') {
          continue;
        }

        const checkedKey = key as Exclude<keyof ValidityState, 'valid'>;

        if (formControl.validity[checkedKey]) {
          validity.invalidKeys.push(checkedKey);
        }
      }

      return validity;
    },
  };
};

import type { Validator } from '../webawesome-form-associated-element.js';

export interface RequiredValidatorOptions {
  /** This is a cheap way for us to get translation strings for the user without having proper translations. */
  validationElement?: HTMLSelectElement | HTMLInputElement;

  /**
   * The property to check if its not null-ish. For most elements this will be "value".
   * For "checkbox" for example it will be "checked"
   */
  validationProperty?: string;
}

export const RequiredValidator = (options: RequiredValidatorOptions = {}): Validator => {
  let { validationElement, validationProperty } = options;

  if (!validationElement) {
    if (typeof document !== 'undefined' && 'createElement' in document) {
      validationElement = Object.assign(document.createElement('input'), { required: true });
    }
  }

  if (!validationProperty) {
    validationProperty = 'value';
  }

  const obj: Validator = {
    observedAttributes: ['required'],
    message: validationElement?.validationMessage, // @TODO: Add a translation.
    checkValidity(element) {
      const validity: ReturnType<Validator['checkValidity']> = {
        message: '',
        isValid: true,
        invalidKeys: [],
      };

      const isRequired = element.required ?? element.hasAttribute('required');

      // Always true if the element isn't required.
      if (!isRequired) {
        return validity;
      }

      const value = element[validationProperty as keyof typeof element];

      const isEmpty = !value;

      if (isEmpty) {
        validity.message = typeof obj.message === 'function' ? obj.message(element) : obj.message || '';
        validity.isValid = false;
        validity.invalidKeys.push('valueMissing');
      }

      return validity;
    },
  };

  return obj;
};

import type WaSlider from '../../components/slider/slider.js';
import type { Validator } from '../webawesome-form-associated-element.js';

/**
 * True when `value` isn't aligned to the step grid anchored at `min`. The step count is compared to the nearest integer
 * with a small tolerance so values that legitimately land on the grid (e.g. `0.3` with a step of `0.1`) aren't rejected
 * because of floating-point error, matching the native `<input>` step-mismatch behavior.
 */
function isStepMismatch(value: number, min: number, step: number): boolean {
  const steps = (value - min) / step;
  return Math.abs(steps - Math.round(steps)) > 1e-9;
}

/**
 * Comprehensive validator for sliders that handles range and step validation
 */
export const SliderValidator = (): Validator<WaSlider> => {
  return {
    observedAttributes: ['min', 'max', 'step'],
    checkValidity(element) {
      const validity: ReturnType<Validator['checkValidity']> = {
        message: '',
        isValid: true,
        invalidKeys: [],
      };

      // Create native range input to get localized validation messages
      const createNativeRange = (value: number, min: number, max: number, step: number) => {
        if (typeof document === 'undefined') {
          return '';
        }

        const input = document.createElement('input');
        input.type = 'range';
        input.min = String(min);
        input.max = String(max);
        input.step = String(step);
        input.value = String(value);

        // Trigger validation
        input.checkValidity();
        return input.validationMessage;
      };

      // For range sliders, validate both values
      if (element.isRange) {
        const minValue = element.minValue;
        const maxValue = element.maxValue;

        // Check range underflow for min value
        if (minValue < element.min) {
          validity.isValid = false;
          validity.invalidKeys.push('rangeUnderflow');
          validity.message =
            createNativeRange(minValue, element.min, element.max, element.step) ||
            `Value must be greater than or equal to ${element.min}.`;
          return validity;
        }

        // Check range overflow for max value
        if (maxValue > element.max) {
          validity.isValid = false;
          validity.invalidKeys.push('rangeOverflow');
          validity.message =
            createNativeRange(maxValue, element.min, element.max, element.step) ||
            `Value must be less than or equal to ${element.max}.`;
          return validity;
        }

        // Check step mismatch
        if (element.step && element.step !== 1) {
          const minStepMismatch = isStepMismatch(minValue, element.min, element.step);
          const maxStepMismatch = isStepMismatch(maxValue, element.min, element.step);

          if (minStepMismatch || maxStepMismatch) {
            validity.isValid = false;
            validity.invalidKeys.push('stepMismatch');
            const testValue = minStepMismatch ? minValue : maxValue;
            validity.message =
              createNativeRange(testValue, element.min, element.max, element.step) ||
              `Value must be a multiple of ${element.step}.`;
            return validity;
          }
        }
      } else {
        // Single value validation
        const value = element.value;

        // Check range underflow
        if (value < element.min) {
          validity.isValid = false;
          validity.invalidKeys.push('rangeUnderflow');
          validity.message =
            createNativeRange(value, element.min, element.max, element.step) ||
            `Value must be greater than or equal to ${element.min}.`;
          return validity;
        }

        // Check range overflow
        if (value > element.max) {
          validity.isValid = false;
          validity.invalidKeys.push('rangeOverflow');
          validity.message =
            createNativeRange(value, element.min, element.max, element.step) ||
            `Value must be less than or equal to ${element.max}.`;
          return validity;
        }

        // Check step mismatch
        if (element.step && element.step !== 1 && isStepMismatch(value, element.min, element.step)) {
          validity.isValid = false;
          validity.invalidKeys.push('stepMismatch');
          validity.message =
            createNativeRange(value, element.min, element.max, element.step) ||
            `Value must be a multiple of ${element.step}.`;
          return validity;
        }
      }

      return validity;
    },
  };
};

import type WaTagInput from '../../components/tag-input/tag-input.js';
import type { Validator } from '../webawesome-form-associated-element.js';

/**
 * Validates the number of tags in a tag input against `required`, `min-tags`, and `max-tags`. The built-in required
 * validator only checks whether the value is falsy, which an empty array never is, so tag inputs need their own.
 */
export const TagInputValidator = (): Validator<WaTagInput> => {
  // Borrow the browser's localized "Please fill out this field." message, like the required validator does
  const nativeRequired =
    typeof document !== 'undefined' && 'createElement' in document
      ? Object.assign(document.createElement('input'), { required: true })
      : undefined;

  return {
    observedAttributes: ['required', 'min-tags', 'max-tags'],
    checkValidity(element) {
      const validity: ReturnType<Validator['checkValidity']> = {
        message: '',
        isValid: true,
        invalidKeys: [],
      };

      const count = element.value.length;

      if (element.required && count === 0) {
        validity.isValid = false;
        validity.invalidKeys.push('valueMissing');
        validity.message = nativeRequired?.validationMessage || 'Please fill out this field.';
        return validity;
      }

      // Zero tags on an optional control stays valid, like minlength on an empty input
      if (element.minTags != null && count > 0 && count < element.minTags) {
        validity.isValid = false;
        validity.invalidKeys.push('rangeUnderflow');
        validity.message = element.localize.term('tooFewTags', element.minTags);
        return validity;
      }

      if (element.maxTags != null && count > element.maxTags) {
        validity.isValid = false;
        validity.invalidKeys.push('rangeOverflow');
        validity.message = element.localize.term('tooManyTags', element.maxTags);
      }

      return validity;
    },
  };
};

import type { LitElement } from 'lit';

type UpdateHandler = (prev?: unknown, next?: unknown) => void;

type NonUndefined<A> = A extends undefined ? never : A;

type UpdateHandlerFunctionKeys<T extends object> = {
  [K in keyof T]-?: NonUndefined<T[K]> extends UpdateHandler ? K : never;
}[keyof T];

interface WatchOptions {
  /**
   * If true, will only start watching after the initial update/render
   */
  waitUntilFirstUpdate?: boolean;
}

/**
 * Runs when observed properties change, e.g. @property or @state, but before the component updates. To wait for an
 * update to complete after a change occurs, use `await this.updateComplete` in the handler. To start watching after the
 * initial update/render, use `{ waitUntilFirstUpdate: true }` or `this.hasUpdated` in the handler.
 *
 * Usage:
 *
 * @watch('propName')
 * handlePropChange(oldValue, newValue) {
 *   ...
 * }
 */
export function watch(propertyName: string | string[], options?: WatchOptions) {
  const resolvedOptions: Required<WatchOptions> = {
    waitUntilFirstUpdate: false,
    ...options,
  };
  return <ElemClass extends LitElement>(proto: ElemClass, decoratedFnName: UpdateHandlerFunctionKeys<ElemClass>) => {
    // @ts-expect-error - update is a protected property
    const { update } = proto;
    const watchedProperties = Array.isArray(propertyName) ? propertyName : [propertyName];

    // @ts-expect-error - update is a protected property
    proto.update = function (this: ElemClass, changedProps: Map<keyof ElemClass, ElemClass[keyof ElemClass]>) {
      watchedProperties.forEach(property => {
        const key = property as keyof ElemClass;
        if (changedProps.has(key)) {
          const oldValue = changedProps.get(key);
          const newValue = this[key];

          if (oldValue !== newValue) {
            if (!resolvedOptions.waitUntilFirstUpdate || this.hasUpdated) {
              (this[decoratedFnName] as unknown as UpdateHandler)(oldValue, newValue);
            }
          }
        }
      });

      update.call(this, changedProps);
    };
  };
}

import type { CSSResultGroup, PropertyValues } from 'lit';
import { LitElement, isServer } from 'lit';
import { property } from 'lit/decorators.js';
import hostStyles from '../styles/component/host.styles.js';

// Augment Lit's module
declare module 'lit' {
  interface PropertyDeclaration {
    /**
     * Specifies the property's default value
     */
    default?: any;
    initial?: any;
  }
}

const HAS_ENDING_COLON = /;\s+$/;

function camelToKebab(str: string) {
  return str.replace(/[A-Z]/g, c => `-${c.toLowerCase()}`);
}

// if your server doesn't have a polyfill available for this.style, (assumed by it being undefined) we modify the attribute directly.
function buildStyleAttribute(options: { property?: string | null; value?: unknown; element: HTMLElement }) {
  const { property, value, element } = options;
  if (value) {
    let style = element.getAttribute('style') || '';
    if (style) {
      // need to check if the previous property ended with a colon or not.
      if (!style.match(HAS_ENDING_COLON)) {
        style += ';';
      }
      style += ' ';
    }

    const str = `${property}: ${value}`;

    if (style.includes(str)) {
      return;
    }

    return `${style}${str};`;
  }

  return null;
}

/**
 * @internal
 */
export default class WebAwesomeElement extends LitElement {
  // One or more CSSResultGroup to include in the component's shadow root. Host styles are automatically prepended.
  static css?: CSSResultGroup;

  /** Prepends host styles to the component's styles. */
  static get styles(): CSSResultGroup {
    const styles = Array.isArray(this.css) ? this.css : this.css ? [this.css] : [];
    return [hostStyles, ...styles];
  }

  #hasRecordedInitialProperties = false;
  initialReflectedProperties: Map<string, unknown> = new Map();
  internals: ElementInternals;

  // Make localization attributes reactive
  @property() dir: string;
  @property() lang: string;
  @property({ type: Boolean, reflect: true, attribute: 'did-ssr' }) didSSR = isServer || Boolean(this.shadowRoot);

  constructor() {
    super();

    try {
      this.internals = this.attachInternals();
    } catch {
      /* Need to tell people if they need a polyfill. */
      /* eslint-disable-next-line */
      console.error('Element internals are not supported in your browser. Consider using a polyfill');
    }

    this.customStates.set('wa-defined', true);

    let Self = this.constructor as typeof WebAwesomeElement;
    for (let [property, spec] of Self.elementProperties) {
      if (spec.default === 'inherit' && spec.initial !== undefined && typeof property === 'string') {
        this.customStates.set(`initial-${property}-${spec.initial}`, true);
      }
    }
  }

  connectedCallback() {
    super.connectedCallback();

    // SSR guard: document is not available during server-side rendering
    if (!this.didSSR) {
      // Helpful comment node inside the shadow root that links to the docs
      this.shadowRoot?.prepend(
        document.createComment(
          ` Web Awesome: https://webawesome.com/docs/components/${this.localName.replace('wa-', '')} `,
        ),
      );
    }

    if (this.didSSR) {
      this.updateComplete.then(() => {
        // Helpful comment node inside the shadow root that links to the docs
        this.shadowRoot?.prepend(
          document.createComment(
            ` Web Awesome: https://webawesome.com/docs/components/${this.localName.replace('wa-', '')} `,
          ),
        );
      });
    }
  }

  attributeChangedCallback(name: string, oldValue: string | null, newValue: string | null) {
    if (!this.#hasRecordedInitialProperties) {
      (this.constructor as typeof WebAwesomeElement).elementProperties.forEach(
        (obj, prop: keyof typeof this & string) => {
          // eslint-disable-next-line
          if (obj.reflect && this[prop] != null) {
            this.initialReflectedProperties.set(prop, this[prop]);
          }
        },
      );

      this.#hasRecordedInitialProperties = true;
    }

    super.attributeChangedCallback(name, oldValue, newValue);
  }

  protected willUpdate(changedProperties: Parameters<LitElement['willUpdate']>[0]): void {
    super.willUpdate(changedProperties);

    // Run the morph fixing *after* willUpdate.
    this.initialReflectedProperties.forEach((value, prop: string & keyof typeof this) => {
      // If a prop changes to `null`, we assume this happens via an attribute changing to `null`.
      // eslint-disable-next-line
      if (changedProperties.has(prop) && this[prop] == null) {
        // Silly type gymnastics to appease the compiler.
        (this as Record<string, unknown>)[prop] = value;
      }
    });
  }

  protected firstUpdated(changedProperties: Parameters<LitElement['firstUpdated']>[0]): void {
    super.firstUpdated(changedProperties);

    // This is a fix to workaround SSR not being able to catch slotchange events.
    // https://github.com/lit/lit/discussions/4697
    if (this.didSSR) {
      this.shadowRoot?.querySelectorAll('slot').forEach(slotElement => {
        slotElement.dispatchEvent(new Event('slotchange', { bubbles: true, composed: false, cancelable: false }));
      });
    }
  }

  protected update(changedProperties: PropertyValues<this>): void {
    try {
      super.update(changedProperties);
    } catch (e) {
      if (this.didSSR && !this.hasUpdated) {
        // Emit a hydration error so we can catch it and do cool things.
        // This may accidentally grab non-hydration related errors, but its the best I've found without directly reading error strings.
        const event = new Event('lit-hydration-error', { bubbles: true, composed: true, cancelable: false });
        // @ts-expect-error leave me alone TS.
        event.error = e;
        this.dispatchEvent(event);
        // console.error(e);
      }
      throw e;
    }
  }

  /**
   * @internal
   * Internal way to set styles across both client and server
   */
  protected setStyle<T extends keyof CSSStyleDeclaration & string>(property: T, value: CSSStyleDeclaration[T]) {
    // if your server doesn't have a polyfill available for this.style, (assumed by it being undefined) we modify the attribute directly.
    if (!this.style) {
      const str = buildStyleAttribute({
        // because this is going to be serialized to an HTML style attribute, need to transform the casing.
        property: camelToKebab(property),
        value,
        element: this,
      });

      if (str) {
        this.setAttribute('style', str);
      }

      return;
    }

    // Client side
    this.style[property] = value;
  }

  /**
   * @internal
   * Internal way to set a CSS custom property across both client and server.
   */
  protected setStyleProperty<T extends string>(property: T, value: string) {
    // if your server doesn't have a polyfill available for this.style, (assumed by it being undefined) we modify the attribute directly.
    if (!this.style) {
      const str = buildStyleAttribute({
        // because this is going to be serialized to an HTML style attribute, need to transform the casing.
        property,
        value,
        element: this,
      });

      if (str) {
        this.setAttribute('style', str);
      }

      return;
    }

    // Client side
    this.style.setProperty(property, value);
  }

  /**
   * @internal Methods for setting and checking custom states.
   */
  public customStates = {
    /** Adds or removes the specified custom state. */
    set: (customState: string, active: boolean) => {
      if (!Boolean(this.internals?.states)) return;
      try {
        if (active) {
          this.internals.states.add(customState);
        } else {
          this.internals.states.delete(customState);
        }
      } catch (e) {
        if (String(e).includes("must start with '--'")) {
          /* eslint-disable-next-line */
          console.error('Your browser implements an outdated version of CustomStateSet. Consider using a polyfill');
        } else {
          throw e;
        }
      }
    },

    /** Determines whether or not the element currently has the specified state. */
    has: (customState: string) => {
      if (!Boolean(this.internals?.states)) return false;
      try {
        return this.internals.states.has(customState);
      } catch {
        return false;
      }
    },
  };

  /**
   * @internal Given a native event, this function cancels it and dispatches it again from the host element using the desired
   * event options.
   */
  relayNativeEvent(event: Event, eventOptions?: EventInit) {
    event.stopImmediatePropagation();

    // This triggers an error in CEM, so we need to ignore it.
    /** @internal */
    this.dispatchEvent(
      new (event.constructor as typeof Event)(event.type, {
        ...event,
        ...eventOptions,
      }),
    );
  }
}

import { LitElement, isServer } from 'lit';
import { property } from 'lit/decorators.js';
import { WaInvalidEvent } from '../events/invalid.js';
import { CustomErrorValidator } from './validators/custom-error-validator.js';
import WebAwesomeElement from './webawesome-element.js';

export interface Validator<T extends WebAwesomeFormAssociatedElement = WebAwesomeFormAssociatedElement> {
  observedAttributes?: string[];
  checkValidity: (element: T) => {
    message: string;
    isValid: boolean;
    invalidKeys: Exclude<keyof ValidityState, 'valid'>[];
  };
  message?: string | ((element: T) => string);
}

export interface WebAwesomeFormControl extends WebAwesomeElement {
  // Form attributes
  name: null | string;
  disabled?: boolean;
  defaultValue?: unknown;
  defaultChecked?: boolean;
  checked?: boolean;
  defaultSelected?: boolean;
  selected?: boolean;
  get form(): HTMLFormElement | null;
  set form(val: string);

  value?: unknown;

  // Constraint validation attributes
  pattern?: string;
  min?: number | string | Date;
  max?: number | string | Date;
  step?: number | 'any';
  required?: boolean;
  minlength?: number;
  maxlength?: number;

  // Form validation properties
  readonly validity: ValidityState;
  readonly validationMessage: string;

  // Form validation methods
  checkValidity: () => boolean;
  getForm: () => HTMLFormElement | null;
  reportValidity: () => boolean;
  setCustomValidity: (message: string) => void;

  // Form properties
  hasInteracted: boolean;
  valueHasChanged?: boolean;

  /** Convenience API for `setCustomValidity()` */
  customError: null | string;
}

// setFormValue omitted so that we can use `setValue`
export class WebAwesomeFormAssociatedElement
  extends WebAwesomeElement
  implements Omit<ElementInternals, 'form' | 'setFormValue'>, WebAwesomeFormControl
{
  static formAssociated = true;

  /**
   * Validators are static because they have `observedAttributes`, essentially attributes to "watch"
   * for changes. Whenever these attributes change, we want to be notified and update the validator.
   */
  static get validators(): Validator[] {
    return isServer ? [] : [CustomErrorValidator()];
  }

  // Append all Validator "observedAttributes" into the "observedAttributes" so they can run.
  static get observedAttributes() {
    const parentAttrs = new Set(super.observedAttributes || []);

    for (const validator of this.validators) {
      if (!validator.observedAttributes) {
        continue;
      }

      for (const attr of validator.observedAttributes) {
        parentAttrs.add(attr);
      }
    }

    return [...parentAttrs];
  }

  // Form attributes
  /** The name of the input, submitted as a name/value pair with form data. */
  @property({ reflect: true }) name: string | null = null;

  /** Disables the form control. */
  @property({ type: Boolean }) disabled = false;

  required: boolean = false;

  assumeInteractionOn: string[] = ['input'];

  // Additional
  input?: (HTMLElement & { value: unknown }) | HTMLInputElement | HTMLTextAreaElement;

  validators: Validator[] = [];

  // Should these be private?
  @property({ state: true, attribute: false }) valueHasChanged: boolean = false;
  @property({ state: true, attribute: false }) hasInteracted: boolean = false;

  // This works around a limitation in Safari. It is a hacky way for us to preserve custom errors generated by the user.
  @property({ attribute: 'custom-error', reflect: true }) customError: string | null = null;

  private emittedEvents: string[] = [];

  constructor() {
    super();

    if ('addEventListener' in this) {
      // eslint-disable-next-line
      this.addEventListener('invalid', this.emitInvalid);
    }
  }
  states: CustomStateSet;

  connectedCallback() {
    super.connectedCallback();
    if (this.didSSR && !this.hasUpdated) {
      this.updateComplete.then(() => {
        this.updateValidity();
      });
    } else {
      this.updateValidity();
    }

    // Lazily evaluate after the constructor to allow people to override the `assumeInteractionOn`
    this.assumeInteractionOn.forEach(event => {
      this.addEventListener?.(event, this.handleInteraction);
    });
  }

  firstUpdated(...args: Parameters<LitElement['firstUpdated']>) {
    super.firstUpdated(...args);
    this.updateValidity();
