    /* #endregion */
  }
}

@layer wa-theme-overrides {
  .wa-theme-shoelace {
    wa-avatar {
      background-color: var(--wa-color-neutral-fill-loud);
      color: var(--wa-color-neutral-on-loud);
    }

    /* Give button labels a font-size one step smaller
     * than their size class or attribute */
    wa-button {
      &::part(label) {
        font-size: var(--wa-font-size-s);
      }

      &[size='xs']::part(label),
      &.wa-size-xs::part(label) {
        font-size: var(--wa-font-size-2xs);
      }

      &[size='s']::part(label),
      &[size='small']::part(label) /* deprecated */,
      &.wa-size-s::part(label) {
        font-size: var(--wa-font-size-xs);
      }

      &[size='l']::part(label),
      &[size='large']::part(label) /* deprecated */,
      &.wa-size-l::part(label) {
        font-size: var(--wa-font-size-m);
      }

      &[size='xl']::part(label),
      &.wa-size-xl::part(label) {
        font-size: var(--wa-font-size-l);
      }
    }

    /* Because we can't set the font-size of just the label text
     * and button padding and height are em-based,
     * store the intended size in a private property for use in calculations */
    button,
    input:is([type='button'], [type='reset'], [type='submit']),
    a.wa-button {
      --_size: var(--wa-font-size-m);
      font-size: var(--wa-font-size-s);

      &[size='xs'],
      &.wa-size-xs {
        --_size: var(--wa-font-size-xs);
        font-size: var(--wa-font-size-2xs);
      }

      &[size='s'],
      &[size='small'] /* deprecated */,
      &.wa-size-s {
        --_size: var(--wa-font-size-s);
        font-size: var(--wa-font-size-xs);
      }

      &[size='l'],
      &[size='large'] /* deprecated */,
      &.wa-size-l {
        --_size: var(--wa-font-size-l);
        font-size: var(--wa-font-size-m);
      }

      &[size='xl'],
      &.wa-size-xl {
        --_size: var(--wa-font-size-xl);
        font-size: var(--wa-font-size-l);
      }

      /* Override em-based properties to use the intended size
       * so that height and padding match inputs at the same size,
       * even though the button's font-size is one step smaller */
      --wa-form-control-padding-block: calc(0.75 * var(--_size));
      --wa-form-control-padding-inline: var(--_size);
      --wa-form-control-height: round(
        calc(2 * var(--wa-form-control-padding-block) + var(--_size) * var(--wa-form-control-value-line-height)),
        1px
      );
    }

    wa-radio[appearance='button'] {
      font-weight: var(--wa-font-weight-action);

      &::part(label) {
        font-size: var(--wa-font-size-s);
      }

      &[size='xs']::part(label),
      &.wa-size-xs::part(label) {
        font-size: var(--wa-font-size-2xs);
      }

      &[size='s']::part(label),
      &[size='small']::part(label) /* deprecated */,
      &.wa-size-s::part(label) {
        font-size: var(--wa-font-size-xs);
      }

      &[size='l']::part(label),
      &[size='large']::part(label) /* deprecated */,
      &.wa-size-l::part(label) {
        font-size: var(--wa-font-size-m);
      }

      &[size='xl']::part(label),
      &.wa-size-xl::part(label) {
        font-size: var(--wa-font-size-l);
      }

      &:state(checked) {
        background-color: var(--wa-form-control-activated-color);
        color: var(--wa-color-brand-on-loud);
      }
    }

    /* Propagate the font-size of wa-radio-group to its children */
    wa-radio-group {
      &:is([size='xs'], .wa-size-xs) wa-radio[appearance='button']::part(label) {
        font-size: var(--wa-font-size-2xs);
      }
      &:is([size='s'], [size='small'] /* deprecated */, .wa-size-s) wa-radio[appearance='button']::part(label) {
        font-size: var(--wa-font-size-xs);
      }
      &:is([size='m'], [size='medium'] /* deprecated */, .wa-size-m) wa-radio[appearance='button']::part(label) {
        font-size: var(--wa-font-size-s);
      }
      &:is([size='l'], [size='large'] /* deprecated */, .wa-size-l) wa-radio[appearance='button']::part(label) {
        font-size: var(--wa-font-size-m);
      }
      &:is([size='xl'], .wa-size-xl) wa-radio[appearance='button']::part(label) {
        font-size: var(--wa-font-size-l);
      }
    }

    wa-breadcrumb {
      font-size: var(--wa-font-size-s);
    }

    wa-callout {
      padding: var(--wa-space-m);
      font-size: var(--wa-font-size-s);

