      &[size='small'] /* deprecated */,
      &.wa-size-s {
        padding: var(--wa-space-s);
        font-size: var(--wa-font-size-xs);
      }

      &[size='l'],
      &[size='large'] /* deprecated */,
      &.wa-size-l {
        padding: var(--wa-space-l);
        font-size: var(--wa-font-size-m);
      }

      &[size='xl'],
      &.wa-size-xl {
        padding: var(--wa-space-xl);
        font-size: var(--wa-font-size-l);
      }

      /* Give outlined callouts a top accent border */
      &[appearance='outlined'] {
        border-color: var(--wa-color-surface-border);
        border-top-color: var(--wa-color-border-loud);
        border-top-width: var(--wa-border-width-l);
      }
    }

    /* Use unique focus styles for text-based inputs */
    :is(
        wa-input,
        wa-textarea,
        wa-select,
        wa-combobox,
        wa-tag-input,
        input:not(
            [type='button'],
            [type='checkbox'],
            [type='color'],
            [type='file'],
            [type='hidden'],
            [type='image'],
            [type='radio'],
            [type='range'],
            [type='reset'],
            [type='submit']
