      --wa-focus-ring-offset: 0;

      &:focus-within {
        &:where(:not(wa-input, wa-textarea, wa-select, wa-combobox, wa-tag-input)),
        &:where(wa-input)::part(base),
        &:where(wa-textarea)::part(base),
        &:where(wa-select)::part(combobox),
        &:where(wa-combobox)::part(combobox),
        &:where(wa-tag-input)::part(tag-input) {
          border-color: var(--wa-color-brand-border-loud);
        }
      }
    }

    wa-radio,
    input[type='radio'] {
      --checked-icon-color: var(--wa-color-surface-default);
      --checked-icon-scale: 0.4;

      &:state(checked)::part(control), /* for wa-radio */
      &:checked /* for input[type='radio'] */ {
        background-color: var(--wa-form-control-activated-color);
      }
    }

    wa-slider::part(thumb) {
      border: none;
    }

    /* Separate range thumb selectors into their own rules
     * so that Safari can process the ::-webkit- selector
     * before exiting on the ::-moz- selector */
