      &::-webkit-slider-thumb {
        border: none;
      }

      &::-moz-range-thumb {
        border: none;
      }
    }

    wa-switch {
      --height: calc(1em * var(--wa-form-control-value-line-height) - var(--wa-form-control-border-width) * 2);
      --thumb-size: calc(var(--height) + 0.25em);
      --width: calc(var(--height) * 2);

      &::part(control) {
        background-color: var(--wa-color-gray-60);
        border-color: var(--wa-color-gray-60);
      }

      &::part(thumb) {
        background-color: var(--wa-color-surface-default);
        border: var(--wa-border-width-s) var(--wa-border-style) var(--wa-color-gray-60);
      }

      &:state(checked) {
        &::part(control) {
          background-color: var(--wa-form-control-activated-color);
          border-color: var(--wa-form-control-activated-color);
        }

        &::part(thumb) {
          border-color: var(--wa-form-control-activated-color);
        }
      }
    }

    wa-tab {
      font-size: var(--wa-font-size-s);
    }
  }
}

