  }

  return kitCode;
}

/**
 * Recursively clones plain objects and arrays, passing everything else (functions, class instances, DOM nodes, dates,
 * maps, sets, etc.) through by reference. Unlike `structuredClone`, this won't throw on non-serializable values, which
 * makes it useful for defensively copying config objects that may contain callbacks (e.g. Chart.js configs).
 *
 * Only the spine of plain objects and arrays is duplicated. Non-plain values are shared, not copied, so mutating one
 * through the clone also mutates the original. Circular references are handled. For JSON-safe data, use
 * `structuredClone` instead.
 */
export function deepClone<T>(value: T, seen = new WeakMap<object, unknown>()): T {
  // Primitives and functions are returned as-is. Functions are intentionally passed through by reference.
  if (value === null || typeof value !== 'object') {
    return value;
  }

  // Guard against circular references.
  if (seen.has(value as object)) {
    return seen.get(value as object) as T;
  }

  if (Array.isArray(value)) {
    const result: unknown[] = [];
    seen.set(value as object, result);
    for (const item of value) {
      result.push(deepClone(item, seen));
    }
    return result as T;
  }

  // Only clone plain objects. Class instances, Dates, Maps, DOM nodes, etc. are passed through by reference so we
  // don't accidentally strip their prototype or break their internal state.
  if (Object.getPrototypeOf(value) === Object.prototype || Object.getPrototypeOf(value) === null) {
    const result: Record<string, unknown> = {};
    seen.set(value as object, result);
    for (const key of Object.keys(value as Record<string, unknown>)) {
      result[key] = deepClone((value as Record<string, unknown>)[key], seen);
    }
    return result as T;
  }

  return value;
}

export default deepClone;

/**
 * Returns `true` if the value is a plain object — i.e. an object literal whose prototype is `Object.prototype`. Arrays,
 * `null`, class instances, `Date`, `Map`, DOM nodes, etc. all return `false`. Useful for deciding whether a value can be
 * safely recursed into and merged key-by-key.
 */
export function isPlainObject(value: unknown): value is Record<string, unknown> {
  return (
    typeof value === 'object' &&
    value !== null &&
    !Array.isArray(value) &&
    Object.getPrototypeOf(value) === Object.prototype
  );
}

/**
 * Recursively merges `target` into a clone of `src`, returning a new object. Where both sides hold a plain object at the
 * same key, the two are merged recursively; otherwise `target`'s value overrides `src`'s. Arrays and non-plain values
 * (functions, class instances, etc.) are not merged element-by-element — `target` replaces `src` wholesale at that key.
 *
 * `src` is never mutated (it is cloned via {@link deepClone}, so functions and other non-serializable values it
 * contains are preserved by reference). `target`'s values are assigned by reference, so do not mutate the result's
 * nested objects if you need `target` to stay pristine.
 */
export function deepMerge<T extends Record<string, unknown>, U extends Record<string, unknown>>(
  src: T,
  target: U,
): T & U {
  const result = deepClone(src) as any;

  for (const key in target) {
    if (Object.prototype.hasOwnProperty.call(target, key)) {
      const targetValue = target[key];
      const srcValue = result[key];

      // If both values are plain objects, merge them recursively
      if (isPlainObject(targetValue) && isPlainObject(srcValue)) {
        result[key] = deepMerge(srcValue, targetValue);
      } else {
        // Otherwise, target overrides src
        result[key] = targetValue;
      }
    }
  }

  return result;
}

interface AllDefinedOptions {
  /**
   * A callback that accepts a custom element tag name and returns `true` if the custom element should be defined before
   * resolving or `false` to skip it. The tag name is always in lowercase.
   */
  match: (tagName: string) => boolean;

  /**
   * To wait for additional custom elements that may not be on the page when the function is called, provide them here.
   */
  additionalElements: string | string[];

  /**
   * The root in which to look for custom elements. Defaults to `document`. By design, shadow roots are not traversed,
   * but you can call this function and set `root` to a custom element's shadow root if needed.
   */
  root: Document | ShadowRoot;
}

/**
 * Waits for custom elements that are currently on the page to be registered before resolving. This is sugar for
 * awaiting `customElements.whenDefined()` multiple times. By default, the function waits for all undefined Web Awesome
 * elements, but you can pass a custom match function to wait for other custom elements instead.
 *
 * The function returns with `Promise.all()`, so any loading errors will cause it to reject. Make sure you handle errors
 * accordingly using a try/catch block or a `.catch()`.
 *
 * @example
 * // Wait for Web Awesome elements
 * await allDefined();
 *
 * // Wait for all custom elements that start with `foo-` as well as the `<bar-button>` element
 * await allDefined({
 *   match: tagName => tagName.startsWith('foo-'),
 *   additionalElements: ['bar-button', 'baz-dialog']
 * });
 */
export async function allDefined(options?: Partial<AllDefinedOptions>) {
  const opts: AllDefinedOptions = {
    match: tagName => tagName.startsWith('wa-'),
    additionalElements: [],
    root: document,
    ...options,
  };

  // Ensure additional elements is an array
  const additionalElements = Array.isArray(opts.additionalElements)
    ? opts.additionalElements
    : [opts.additionalElements];

  // Discover undefined elements in the document
  const undefinedElements = [...opts.root.querySelectorAll(':not(:defined)')]
    .map(el => el.localName)
    .filter((tag, index, arr) => arr.indexOf(tag) === index) // make it unique
    .filter(tag => opts.match(tag)); // make sure it matches

  const tagsToAwait = [...undefinedElements, ...additionalElements];

  // Wait for all to be registered
  await Promise.all(tagsToAwait.map(tag => customElements.whenDefined(tag)));

  // Wait a cycle for the first update
  await new Promise(requestAnimationFrame);
}

/**
 * Serializes a form and returns a plain object. If a form control with the same name appears more than once, the
 * property will be converted to an array.
 */
export function serialize(form: HTMLFormElement) {
  const formData = new FormData(form);
  const object: Record<string, unknown> = {};

  formData.forEach((value, key) => {
    if (Reflect.has(object, key)) {
      const entry = object[key];
      if (Array.isArray(entry)) {
        entry.push(value);
      } else {
        object[key] = [object[key], value];
      }
    } else {
      object[key] = value;
    }
  });

  return object;
}

import type { Translation as DefaultTranslation } from '@shoelace-style/localize';
import { LocalizeController as DefaultLocalizationController, registerTranslation } from '@shoelace-style/localize';
import en from '../translations/en.js'; // Register English as the default/fallback language

// Extend the controller and apply our own translation interface for better typings
export class LocalizeController extends DefaultLocalizationController<Translation> {
  // Technically '../translations/en.js' is supposed to work via side-effects. However, by some mystery sometimes the
  // translations don't get bundled as expected resulting in `no translation found` errors. This is basically some extra
  // assurance that our translations get registered prior to our localizer connecting in a component and we don't rely
  // on implicit import ordering.
  static {
    registerTranslation(en);
  }

  lang() {
    // @ts-expect-error
    if (this.host.didSSR && !this.host.hasUpdated) {
      // On the server and on first hydration we can't rely on the document language (right now)
      // TODO: We should write a custom renderer that can understand a lang tree.
      return this.host.lang || 'en';
    }

    return super.lang();
  }
}

